public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H1 = Integer.parseInt(st.nextToken());
        int W1 = Integer.parseInt(st.nextToken());
        int H2 = Integer.parseInt(st.nextToken());
        int W2 = Integer.parseInt(st.nextToken());
        int R = Integer.parseInt(st.nextToken());

        int[] rooms1 = new int[H1 * W1];
        int idx = 0;
        for (int i = 0; i < H1; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < W1; j++) {
                rooms1[idx++] = Integer.parseInt(st.nextToken());
            }
        }
        Arrays.sort(rooms1);

        int[] rooms2 = new int[H2 * W2];
        idx = 0;
        for (int i = 0; i < H2; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < W2; j++) {
                rooms2[idx++] = Integer.parseInt(st.nextToken());
            }
        }
        Arrays.sort(rooms2);

        long ans = Long.MAX_VALUE;

        // Try each possible auth level for office 1: 0, or any room's security level
        // a1 can be 0 (access 0 rooms) or rooms1[i]
        for (int i = -1; i < rooms1.length; i++) {
            long a1 = (i == -1) ? 0 : rooms1[i];
            int cnt1 = (i == -1) ? 0 : (i + 1); // rooms1 is sorted, so rooms1[0..i] are accessible
            // Actually need distinct: if multiple same value, count all with value <= a1
            // Since sorted, cnt1 = upper_bound of a1
            if (i >= 0) {
                // find how many <= rooms1[i]
                cnt1 = upperBound(rooms1, rooms1[i]);
                a1 = rooms1[i];
            }

            int need = R - cnt1;
            if (need <= 0) {
                ans = Math.min(ans, a1);
            } else if (need <= rooms2.length) {
                // need at least 'need' rooms from office2, minimum a2 = rooms2[need-1]
                long a2 = rooms2[need - 1];
                ans = Math.min(ans, a1 + a2);
            }
        }

        System.out.println(ans);
    }

    static int upperBound(int[] arr, int val) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.io.*;
import java.util.*;

/*
 * JOI - Two Offices / authentication levels
 *
 * We have two H x W offices (buildings/floors), each room has a required level.
 * A visitor for one office starts from the elevator hall cell (sr, sc) and may move
 * 4-directionally through rooms whose required level is <= their authentication level.
 *
 * For each office independently, define:
 *   need[k] = minimum authentication level required to be able to access at least k rooms.
 *
 * Then the answer is:
 *   min over k = 0..R of need1[k] + need2[R-k]
 *
 * Key observation for one office:
 * If we process rooms in increasing security level and union adjacent activated rooms,
 * then after activating all rooms with level <= x, the number of accessible rooms is
 * the size of the connected component containing the elevator hall (if activated),
 * otherwise 0. This size only changes when x reaches some room level.
 *
 * Therefore, for one office:
 *   - sort rooms by level
 *   - activate equal-level batches
 *   - maintain DSU on activated cells
 *   - after each batch, let s = accessible size from start, then for all k in
 *     (previous_s+1 .. s), need[k] = current level
 *
 * Complexity per office: O(HW alpha(HW) + HW log(HW))
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class DSU {
        int[] p, sz;

        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            Arrays.fill(p, -1);
        }

        void activate(int x) {
            p[x] = x;
            sz[x] = 1;
        }

        boolean active(int x) {
            return p[x] != -1;
        }

        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }

        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
        }

        int size(int x) {
            return sz[find(x)];
        }
    }

    static class Cell {
        int level, idx;
        Cell(int level, int idx) {
            this.level = level;
            this.idx = idx;
        }
    }

    static int[] computeNeed(int H, int W, int sr, int sc, int[][] a) {
        int n = H * W;
        Cell[] cells = new Cell[n];
        int t = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                cells[t] = new Cell(a[i][j], i * W + j);
                t++;
            }
        }
        Arrays.sort(cells, Comparator.comparingInt(c -> c.level));

        int start = sr * W + sc;
        int[] need = new int[n + 1];
        need[0] = 0;

        DSU dsu = new DSU(n);
        boolean[] active = new boolean[n];
        int filled = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        int i = 0;
        while (i < n) {
            int j = i;
            int level = cells[i].level;

            // Activate all cells with this level
            while (j < n && cells[j].level == level) {
                int idx = cells[j].idx;
                active[idx] = true;
                dsu.activate(idx);
                int r = idx / W;
                int c = idx % W;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (0 <= nr && nr < H && 0 <= nc && nc < W) {
                        int ni = nr * W + nc;
                        if (active[ni]) dsu.union(idx, ni);
                    }
                }
                j++;
            }

            int accessible = 0;
            if (active[start]) accessible = dsu.size(start);

            while (filled < accessible) {
                need[++filled] = level;
            }

            i = j;
        }

        return need;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        int R = fs.nextInt();
        int sr = fs.nextInt() - 1;
        int sc = fs.nextInt() - 1;

        int[][] office1 = new int[H][W];
        int[][] office2 = new int[H][W];

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                office1[i][j] = fs.nextInt();
            }
        }
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                office2[i][j] = fs.nextInt();
            }
        }

        int[] need1 = computeNeed(H, W, sr, sc, office1);
        int[] need2 = computeNeed(H, W, sr, sc, office2);

        long ans = Long.MAX_VALUE;
        int n = H * W;
        for (int k = 0; k <= R; k++) {
            if (k <= n && R - k <= n) {
                long val = (long) need1[k] + need2[R - k];
                if (val < ans) ans = val;
            }
        }

        System.out.println(ans);
    }
}

