int H1, W1, H2, W2;
int si1, sj1, si2, sj2;
vector<vector<int>> grid1, grid2;

int bfs_count(const vector<vector<int>>& grid, int H, int W, int si, int sj, int level) {
    if (grid[si][sj] > level) return 0;
    vector<vector<bool>> vis(H, vector<bool>(W, false));
    queue<pair<int,int>> q;
    q.push({si, sj});
    vis[si][sj] = true;
    int count = 0;
    int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        count++;
        for (auto& d : dirs) {
            int ni = i + d[0], nj = j + d[1];
            if (ni >= 0 && ni < H && nj >= 0 && nj < W && !vis[ni][nj] && grid[ni][nj] <= level) {
                vis[ni][nj] = true;
                q.push({ni, nj});
            }
        }
    }
    return count;
}

