int countReachable(vector<vector<int>>& grid, int r, int c, int H, int W, int threshold) {
    if (grid[r][c] > threshold) return 0;
    vector<vector<bool>> vis(H, vector<bool>(W, false));
    queue<pair<int,int>> q;
    q.push({r,c}); vis[r][c] = true;
    int cnt = 1;
    while (!q.empty()) {
        auto [x,y] = q.front(); q.pop();
        for (int d = 0; d < 4; d++) {
            int nx = x+dx[d], ny = y+dy[d];
            if (nx>=0&&nx<H&&ny>=0&&ny<W&&!vis[nx][ny]&&grid[nx][ny]<=threshold) {
                vis[nx][ny]=true; cnt++; q.push({nx,ny});
            }
        }
    }
    return cnt;
}

