#include <bits/stdc++.h>
using namespace std;

/*
We have two H x W office floors.
A visitor chooses one authentication level for each office: x for office 1, y for office 2.
They can enter rooms with security level <= chosen level.
Starting from the elevator hall (sx, sy) in each office, they may move 4-directionally through enterable rooms.
For each office and threshold t, define f[t] = number of reachable rooms from the hall using only rooms with value <= t.
We need min x + y such that f1[x] + f2[y] >= R.

Key observation:
For one office, as threshold increases, reachable room count changes only when some room value is activated.
We can compute for every distinct threshold value v:
  reachable_count_after_adding_all_rooms_with_value<=v
Then solve two-pointer / prefix minimum over the two monotone sequences.

How to compute reachable counts efficiently:
Process rooms in nondecreasing security level, activating all rooms of the same value together.
Maintain DSU over activated rooms.
For each component, track whether it contains the start room.
After activating a batch of same-value rooms and unioning adjacent active cells, if the start is active,
the reachable count is size(component(start)); otherwise 0.
Record pair (value, reachable_count), compressing equal counts by keeping minimal value for each count frontier.

Then combine the two monotone step functions:
For office 2, build best[level of rooms reached >= k] minimal threshold.
Actually easier: from recorded pairs (val, cnt), create array of pairs with strictly increasing cnt and minimal val.
Add (INF-like impossible) handling.
For each pair in office1, need minimal threshold in office2 to reach at least R-cnt1.
Binary search on cnt in office2.
Also consider using only office2 / only office1 via cnt1 maybe 0; include initial pair (0 threshold?).
Threshold can be any integer, but minimal useful thresholds are room values. If need 0 rooms from an office, threshold 0 suffices.
*/

struct DSU {
    vector<int> p, sz;
    DSU() {}
    DSU(int n): p(n), sz(n,1) { iota(p.begin(), p.end(), 0); }
    int find(int x){ return p[x]==x?x:p[x]=find(p[x]); }
    void unite(int a,int b){
        a=find(a); b=find(b);
        if(a==b) return;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a; sz[a]+=sz[b];
    }
    int size(int x){ return sz[find(x)]; }
};

static const long long INF64 = (1LL<<62);

vector<pair<int,int>> process_office(int H, int W, int sx, int sy, const vector<int>& A){
    int N = H * W;
    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j){
        if (A[i] != A[j]) return A[i] < A[j];
        return i < j;
    });

    DSU dsu(N);
    vector<char> active(N, 0);

    auto inside = [&](int x, int y){
        return 0 <= x && x < H && 0 <= y && y < W;
    };
    auto id = [&](int x, int y){
        return x * W + y;
    };

    int start = id(sx, sy);
    vector<pair<int,int>> res;
    res.push_back({0, 0}); // threshold 0 gives 0 rooms unless start room has 0, but constraints typically positive; still safe as baseline

    int i = 0;
    while (i < N) {
        int v = A[ord[i]];
        int j = i;
        while (j < N && A[ord[j]] == v) {
            int u = ord[j];
            active[u] = 1;
            j++;
        }
        for (int k = i; k < j; k++) {
            int u = ord[k];
            int x = u / W, y = u % W;
            const int dx[4] = {-1,1,0,0};
            const int dy[4] = {0,0,-1,1};
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir], ny = y + dy[dir];
                if (!inside(nx, ny)) continue;
                int vtx = id(nx, ny);
                if (active[vtx]) dsu.unite(u, vtx);
            }
        }

        int cnt = 0;
        if (active[start]) cnt = dsu.size(start);

        if (res.back().second == cnt) {
            // same reachable count; previous threshold is smaller, so ignore
        } else {
            res.push_back({v, cnt});
        }
        i = j;
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, R;
    cin >> H >> W >> R;
    int sx, sy;
    cin >> sx >> sy;
    --sx; --sy;

    vector<int> A1(H * W), A2(H * W);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) cin >> A1[i * W + j];
    }
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) cin >> A2[i * W + j];
    }

    auto P1 = process_office(H, W, sx, sy, A1);
    auto P2 = process_office(H, W, sx, sy, A2);

    // P1, P2: (threshold, reachable_count), counts strictly increasing.
    vector<int> cnt2, val2;
    for (auto &p : P2) {
        val2.push_back(p.first);
        cnt2.push_back(p.second);
    }

    long long ans = INF64;

    for (auto &p : P1) {
        int v1 = p.first;
        int c1 = p.second;
        int need = max(0, R - c1);
        auto it = lower_bound(cnt2.begin(), cnt2.end(), need);
        if (it == cnt2.end()) continue;
        int idx = int(it - cnt2.begin());
        ans = min(ans, (long long)v1 + val2[idx]);
    }

    if (ans == INF64) {
        // Should not happen if R <= 2*H*W, but keep safe.
        cout << -1 << '\n';
    } else {
        cout << ans << '\n';
    }

    return 0;
}

