int main() {
    int h1, w1;
    scanf("%d %d", &h1, &w1);
    int grid1[h1][w1];
    for (int i = 0; i < h1; i++)
        for (int j = 0; j < w1; j++)
            scanf("%d", &grid1[i][j]);
    int sy1, sx1;
    scanf("%d %d", &sy1, &sx1);
    sy1--; sx1--;

    int h2, w2;
    scanf("%d %d", &h2, &w2);
    int grid2[h2][w2];
    for (int i = 0; i < h2; i++)
        for (int j = 0; j < w2; j++)
            scanf("%d", &grid2[i][j]);
    int sy2, sx2;
    scanf("%d %d", &sy2, &sx2);
    sy2--; sx2--;

    int R;
    scanf("%d", &R);

    // For each office, compute the minimal level to reach each cell from elevator
    // Using BFS-like DP with min over neighbors (since we can move up/down/left/right)
    int dist1[h1][w1];
    int visited1[h1][w1];
    memset(visited1, 0, sizeof(visited1));
    for (int i = 0; i < h1; i++)
        for (int j = 0; j < w1; j++)
            dist1[i][j] = INT_MAX;

    // Priority queue approach with simple array since constraints are small
    // We'll do a simple Dijkstra (grid is small enough for O(N^2) updates)
    dist1[sy1][sx1] = grid1[sy1][sx1];
    int dx[] = {1, -1, 0, 0};
    int dy[] = {0, 0, 1, -1};

    for (int iter = 0; iter < h1 * w1; iter++) {
        int minVal = INT_MAX;
        int ux = -1, uy = -1;
        for (int i = 0; i < h1; i++) {
            for (int j = 0; j < w1; j++) {
                if (!visited1[i][j] && dist1[i][j] < minVal) {
                    minVal = dist1[i][j];
                    uy = i;
                    ux = j;
                }
            }
        }
        if (uy == -1) break;
        visited1[uy][ux] = 1;
        for (int d = 0; d < 4; d++) {
            int ny = uy + dy[d];
            int nx = ux + dx[d];
            if (ny >= 0 && ny < h1 && nx >= 0 && nx < w1 && !visited1[ny][nx]) {
                int nd = max(dist1[uy][ux], grid1[ny][nx]);
                if (nd < dist1[ny][nx]) {
                    dist1[ny][nx] = nd;
                }
            }
        }
    }

    int dist2[h2][w2];
    int visited2[h2][w2];
    memset(visited2, 0, sizeof(visited2));
    for (int i = 0; i < h2; i++)
        for (int j = 0; j < w2; j++)
            dist2[i][j] = INT_MAX;

    dist2[sy2][sx2] = grid2[sy2][sx2];
    for (int iter = 0; iter < h2 * w2; iter++) {
        int minVal = INT_MAX;
        int ux = -1, uy = -1;
        for (int i = 0; i < h2; i++) {
            for (int j = 0; j < w2; j++) {
                if (!visited2[i][j] && dist2[i][j] < minVal) {
                    minVal = dist2[i][j];
                    uy = i;
                    ux = j;
                }
            }
        }
        if (uy == -1) break;
        visited2[uy][ux] = 1;
        for (int d = 0; d < 4; d++) {
            int ny = uy + dy[d];
            int nx = ux + dx[d];
            if (ny >= 0 && ny < h2 && nx >= 0 && nx < w2 && !visited2[ny][nx]) {
                int nd = max(dist2[uy][ux], grid2[ny][nx]);
                if (nd < dist2[ny][nx]) {
                    dist2[ny][nx] = nd;
                }
            }
        }
    }

    // Collect all required levels from both offices
    int totalRooms = h1 * w1 + h2 * w2;
    int levels1[h1 * w1];
    int levels2[h2 * w2];
    for (int i = 0; i < h1; i++)
        for (int j = 0; j < w1; j++)
            levels1[i * w1 + j] = dist1[i][j];
    for (int i = 0; i < h2; i++)
        for (int j = 0; j < w2; j++)
            levels2[i * w2 + j] = dist2[i][j];

    qsort(levels1, h1 * w1, sizeof(int), compare);
    qsort(levels2, h2 * w2, sizeof(int), compare);

    // Two-pointer to find minimal sum for at least R rooms
    int ans = INT_MAX;
    int p2 = h2 * w2 - 1;
    for (int p1 = 0; p1 < h1 * w1; p1++) {
        // For current level1 = levels1[p1], find minimal level2 such that rooms >= R
        // rooms from office1 with level <= levels1[p1] = p1+1
        int rooms1 = p1 + 1;
        while (p2 >= 0 && rooms1 + (p2 + 1) >= R) {
            p2--;
        }
        // p2 is now the last index where rooms1 + (p2+1) < R, so next index works
        if (p2 + 1 < h2 * w2) {
            int rooms2 = p2 + 2;
            if (rooms1 + rooms2 >= R) {
                int sum = levels1[p1] + levels2[p2 + 1];
                if (sum < ans) ans = sum;
            }
        }
    }

    // Also consider case where only office2 rooms are used
    if (h2 * w2 >= R) {
        ans = min(ans, levels2[R-1]);
    }
    // Only office1 rooms
    if (h1 * w1 >= R) {
        ans = min(ans, levels1[R-1]);
    }

    printf("%d\n", ans);
    return 0;
}

