#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

#define INF64 ((ll)4e18)

typedef struct {
    int x, y;
} Point;

static int H, W;
static ll Rneed;
static int X, Y; /* elevator hall position (1-indexed in input) */

static int **A1, **A2;
static int *vals1, *vals2;
static int n1, n2;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

static int lower_bound_int(int *arr, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

/* Count reachable rooms from elevator hall with threshold T in one office */
static ll count_reachable(int **A, int T) {
    if (A[X][Y] > T) return 0;

    int N = H * W;
    char *vis = (char *)calloc(N, sizeof(char));
    Point *q = (Point *)malloc(sizeof(Point) * N);
    int head = 0, tail = 0;

    #define ID(i,j) ((i) * W + (j))

    vis[ID(X, Y)] = 1;
    q[tail++] = (Point){X, Y};
    ll cnt = 1;

    static const int dx[4] = {-1, 1, 0, 0};
    static const int dy[4] = {0, 0, -1, 1};

    while (head < tail) {
        Point p = q[head++];
        for (int d = 0; d < 4; d++) {
            int nx = p.x + dx[d];
            int ny = p.y + dy[d];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            int id = ID(nx, ny);
            if (vis[id]) continue;
            if (A[nx][ny] <= T) {
                vis[id] = 1;
                q[tail++] = (Point){nx, ny};
                cnt++;
            }
        }
    }

    free(vis);
    free(q);
    return cnt;
}

/* Build f[k] = minimum threshold needed to access at least k rooms in this office.
   k from 0..H*W. f[0]=0, impossible => INF64 */
static ll *build_min_thresholds(int **A, int *vals, int nvals) {
    int N = H * W;
    ll *best = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 0; i <= N; i++) best[i] = INF64;
    best[0] = 0;

    for (int i = 0; i < nvals; i++) {
        int t = vals[i];
        ll c = count_reachable(A, t);
        if (c > N) c = N;
        if ((ll)t < best[c]) best[c] = t;
    }

    for (int k = N - 1; k >= 0; k--) {
        if (best[k + 1] < best[k]) best[k] = best[k + 1];
    }
    return best;
}

